const inputData = $input.first().json;
const now = new Date();

// Format medical record data for the central hub
const medicalRecord = {
  // Core identifiers
  recordId: `{{CLINIC_PREFIX}}-MR-${Date.now()}`,
  appointmentId: inputData.appointmentId || inputData.petId || inputData.id,

  // Patient information
  petId: inputData.petId || inputData['Pet Name'],
  petName: inputData.petName || inputData['Pet Name'],
  petBreed: inputData.petBreed || inputData['Pet Breed'] || '',
  petAge: inputData.petAge || inputData['Pet Age'] || '',

  // Client information
  clientId: inputData.clientId || inputData['Customer Name'],
  clientName: inputData.clientName || inputData['Customer Name'],
  clientPhone: inputData.clientPhone || inputData['Customer Phone'],
  clientEmail: inputData.clientEmail || inputData['Customer Email'],

  // Visit information
  visitDate: inputData.visitDate || inputData['Date'] || now.toISOString().split('T')[0],
  visitTime: inputData.visitTime || inputData['Time'] || now.toTimeString().split(' ')[0],
  service: inputData.service || inputData['Service'] || 'General Consultation',
  visitType: inputData.visitType || inputData['Service Type'] || 'Standard',

  // Medical details
  visitDetails: inputData.visitDetails || inputData['Notes'] || 'Standard veterinary consultation',
  diagnosis: inputData.diagnosis || inputData['Diagnosis'] || 'Assessment completed',
  treatment: inputData.treatment || inputData['Treatment'] || 'Standard care provided',
  medications: inputData.medications || inputData['Medications'] || '',
  recommendations: inputData.recommendations || inputData['Follow-up'] || '',

  // Staff information
  staffId: inputData.staffId || inputData.assignedStaff || '{{PRIMARY_VET_ID}}',
  staffName: inputData.staffName || inputData.assignedStaffName || '{{HEAD_VETERINARIAN}}',
  veterinarian: inputData.veterinarian || '{{HEAD_VETERINARIAN}}',

  // Record metadata
  recordDate: now.toISOString().split('T')[0],
  recordTime: now.toTimeString().split(' ')[0],
  recordStatus: 'Complete',
  formCompleted: inputData.petHistoryFormCompleted || false,
  notesCompleted: inputData.staffNotesCompleted || true,

  // Additional fields
  weight: inputData.weight || inputData['Pet Weight'] || '',
  temperature: inputData.temperature || '',
  bloodPressure: inputData.bloodPressure || '',
  heartRate: inputData.heartRate || '',
  nextAppointment: inputData.nextAppointment || inputData['Follow-up Date'] || '',
  cost: inputData.cost || inputData['Amount'] || 0,

  // System tracking
  clinic: '{{CLINIC_NAME}}',
  location: '{{CLINIC_ADDRESS}}',
  createdAt: now.toISOString(),
  updatedAt: now.toISOString()
};

return [{
  json: medicalRecord
}];
